const text = ($json.body.subject + ' ' + $json.body.message).toLowerCase();
let priority = 'MEDIUM';

if (text.includes('pork') || text.includes('babi') || text.includes('mirin') || text.includes('sake') || text.includes('expired') || text.includes('kadaluwarsa') || text.includes('non-halal') || text.includes('alkohol')) {
  priority = 'CRITICAL_SAFETY';
} else if (text.includes('urgent') || text.includes('darurat') || text.includes('no signal') || text.includes('tidak ada sinyal') || text.includes('airport')) {
  priority = 'URGENT';
} else if (text.includes('refund') || text.includes('kembalikan dana') || text.includes('rusak') || text.includes('broken')) {
  priority = 'HIGH';
} else if (text.includes('tanya') || text.includes('faq') || text.includes('info')) {
  priority = 'LOW';
}

return { json: { ...$json.body, calculatedPriority: priority } };

